from sim import Sim
import mujoco
sim=Sim()
for objtype,name in [(mujoco.mjtObj.mjOBJ_BODY,'hand'),(mujoco.mjtObj.mjOBJ_BODY,'right_finger'),(mujoco.mjtObj.mjOBJ_BODY,'left_finger'),(mujoco.mjtObj.mjOBJ_SITE,'attachment_site'),(mujoco.mjtObj.mjOBJ_SITE,'grip_site')]:
    try:
        print(objtype, name, mujoco.mj_name2id(sim.model,objtype,name))
    except Exception as e:
        print('missing', objtype, name, e)
print('bodies sample:')
for i in range(sim.model.nbody):
    nm=mujoco.mj_id2name(sim.model,mujoco.mjtObj.mjOBJ_BODY,i)
    if nm and ('finger' in nm or 'hand' in nm or 'panda' in nm):
        print(i,nm)
print('sites sample:')
for i in range(sim.model.nsite):
    nm=mujoco.mj_id2name(sim.model,mujoco.mjtObj.mjOBJ_SITE,i)
    if nm:
        print(i,nm)
